function changedDraft(dataset=false){state.draftRevision++;state.previewRevision++;state.plan=null;state.actionError='';if(dataset)state.datasetReport=null;state.draftStatus='Saving draft…';draftStatus();clearTimeout(draftTimer);draftTimer=setTimeout(saveDraft,350);}
function draftStatus(){const el=$('#draft-status');if(el)el.textContent=state.draftStatus;}
async function saveDraft(){if(!state.draft)return;clearTimeout(draftTimer);const revision=state.draftRevision,payload=JSON.parse(JSON.stringify({...state.draft,spec:trainingSpec()}));draftSaveChain=draftSaveChain.catch(()=>{}).then(()=>api('/api/draft',{draft:payload}));try{await draftSaveChain;if(revision===state.draftRevision)state.draftStatus='Draft saved on this computer';}catch(e){if(revision===state.draftRevision)state.draftStatus='Draft not saved · '+e.message;}draftStatus();}
function field(name,label,{type='text',value,help='',min='',max='',step=''}={}){return `<div class="field"><label for="field-${name}">${label}</label><input id="field-${name}" name="${name}" type="${type}" value="${esc(value??state.draft.spec[name]??'')}"${min!==''?` min="${min}"`:''}${max!==''?` max="${max}"`:''}${step!==''?` step="${step}"`:''}>${help?`<small>${help}</small>`:''}</div>`;}
function selectField(name,label,options,value){return `<div class="field"><label for="field-${name}">${label}</label><select id="field-${name}" name="${name}">${options.map(([id,text])=>`<option value="${esc(id)}" ${String(value)===String(id)?'selected':''}>${esc(text)}</option>`).join('')}</select></div>`;}
function pathField(name,label,purpose,kind,help=''){return `<div class="field full"><label for="field-${name}">${label}</label><div class="path-control"><input id="field-${name}" name="${name}" value="${esc(state.draft.spec[name]||'')}" placeholder="Full path on this computer"><button type="button" class="button" data-action="choose-path" data-target="field-${name}" data-purpose="${purpose}" data-kind="${kind}">Browse…</button></div>${help?`<small>${help}</small>`:''}</div>`;}
const wizardLabels=['Task & data','Training','Compute & limits','Review'];
function newView(){if(!state.draft)state.draft=freshDraft();const step=state.draft.wizard_step;return `${heading('New training','Prepare a classifier, choose your compute, and review the exact plan before launch.')}<ol class="wizard-steps" aria-label="Training setup progress">${wizardLabels.map((label,i)=>`<li class="${i===step?'current':i<step?'complete':''}"><button type="button" data-action="wizard-step" data-step="${i}" ${i>step?'disabled':''} ${i===step?'aria-current="step"':''}><span class="step-number">${i+1}</span>${label}</button></li>`).join('')}</ol><div class="wizard-layout"><form id="training-form" class="wizard-form"><div id="wizard-content">${[taskStep,trainingStep,computeStep,reviewStep][step]()}</div><div id="wizard-error" role="alert">${errorBox(state.actionError)}</div><div class="wizard-actions"><div>${step?'<button type="button" class="button" data-action="wizard-back">Back</button>':'<a class="text-link" href="#jobs">Training runs</a>'}</div>${step<3?'<button type="submit" class="button primary" id="wizard-next">Continue '+icon('arrow')+'</button>':''}</div><p class="draft-status" id="draft-status" aria-live="polite">${esc(state.draftStatus||'Your draft stays on this computer')}</p></form><aside class="wizard-summary"><h2>Before training starts</h2><ul class="plain-list"><li><strong>Check the data</strong><p>Class labels, split sizes, and unreadable files are reported before any provider upload.</p></li><li><strong>Choose the resource order</strong><p>Your primary resource is considered first. Fallbacks keep the same training target.</p></li><li><strong>Keep a recovery point</strong><p>Verify checkpoints and model files. Import notebook results back to this workspace.</p></li></ul></aside></div>`;}
function taskStep(){const d=state.draft,s=d.spec,task=s.recipe==='image'?'image':s.recipe==='custom'?'custom':'tabular';return `<section class="form-section"><h2>What are you training?</h2><div class="task-options">${[['tabular','Tabular classification','A CSV with numeric features and a label column.'],['image','Image classification','Image folders, with one folder per class.']].map(([id,title,description])=>`<label class="task-option ${task===id?'selected':''}"><input type="radio" name="task" value="${id}" ${task===id?'checked':''}><span><strong>${title}</strong><small>${description}</small></span></label>`).join('')}</div><details class="advanced-options" ${task==='custom'?'open':''}><summary>Advanced: my own Python training script</summary><label class="switch-row"><input type="radio" name="task" value="custom" ${task==='custom'?'checked':''}><span><strong>Custom Python</strong><small>Implement reporting, checkpoints, and export hooks.</small></span></label></details></section><section class="form-section"><h2>${task==='image'?'Your image dataset':task==='custom'?'Your training script':'Your tabular dataset'}</h2>${task==='tabular'?`<div class="dataset-options"><label><input type="radio" name="dataset_mode" value="sample" ${d.dataset_mode==='sample'?'checked':''}> Use the working sample dataset</label><label><input type="radio" name="dataset_mode" value="own" ${d.dataset_mode==='own'?'checked':''}> Choose my own CSV</label></div>`:''}${task==='custom'?`${pathField('script_path','Python training script','script','file')}<details class="advanced-options"><summary>Training script contract</summary><p>Build from ctx.resume_state. Call ctx.report(loss, step), poll ctx.should_stop(), and save serializable model state with ctx.checkpoint(state). Finish with ctx.export(files).</p><pre class="example-code">def train(ctx):\n    state = ctx.resume_state or {}\n    # Restore your model here.\n    for step in range(ctx.step + 1, ctx.spec["steps"] + 1):\n        if ctx.should_stop():\n            break\n        # Train, report loss, and checkpoint model state.\n    # Export named model files with ctx.export({...}).</pre></details><label class="switch-row"><input name="trust_script" type="checkbox" ${s.trust_script?'checked':''}><span><strong>I trust this script</strong><small>It runs with my user permissions and can access my files and network.</small></span></label>`:task==='image'?`${pathField('dataset_path','Image dataset folder','image','folder','Example: dataset/cats/photo.jpg and dataset/dogs/photo.jpg. At least 5 images per class; 20% is held out for validation.')}<p class="recipe-description">Choose your own class folders. Inspection decodes images and reports counts and errors before training.</p>`:d.dataset_mode==='own'?`${pathField('dataset_path','Dataset CSV','dataset','file','Numeric feature columns and a binary label: 0 or 1. Inspection previews available columns.')}<div id="label-column-control">${labelColumnField()}</div><details class="advanced-options"><summary>CSV format example</summary><pre class="example-code">height,weight,label\n165,62,1\n151,45,0\n178,78,1</pre><p>Choose the label column. Keep at least 5 examples for each class.</p></details>`:'<p class="recipe-description">The sample is generated numeric classification data for trying this workflow. It does not evaluate your own dataset.</p>'}<div class="button-row" style="margin-top:17px">${action('inspect-data','Check dataset')}${task==='image'?action('environment','Prepare image dependencies','image'):''}</div><div id="dataset-report">${datasetReportView()}</div></section>`;}
function labelColumnField(){const columns=state.datasetReport?.dataset?.columns||state.datasetReport?.dataset?.feature_names||[],names=columns.map(x=>typeof x==='string'?x:x.name).filter(Boolean);return names.length?selectField('label_column','Label column',[['','Last column (default)'],...names.map(x=>[x,x])],state.draft.spec.label_column):field('label_column','Label column (optional)',{help:'Leave blank to use the final CSV column, or enter its header or index.'});}
function datasetReportView(){const r=state.datasetReport;if(!r)return '<p class="field-help" style="margin-top:12px">No dataset inspection has run for this draft yet.</p>';const errors=r.errors||[],warnings=r.warnings||[],d=r.dataset||{};return `<div class="dataset-report"><h3>${errors.length?'Resolve these dataset issues':'Dataset inspection'}</h3>${errors.map(e=>errorBox(typeof e==='string'?e:e.message)).join('')}${!errors.length?`<dl class="report-grid"><div><dt>Examples</dt><dd>${number(d.rows??d.total_images??d.image_count)}</dd></div><div><dt>Training</dt><dd>${number(d.train_rows??d.train_count)}</dd></div><div><dt>Validation</dt><dd>${number(d.validation_rows??d.validation_count)}</dd></div><div><dt>Classes</dt><dd>${Array.isArray(d.classes)?d.classes.length:number(d.class_count??Object.keys(d.class_counts||d.label_distribution||{}).length)}</dd></div></dl>${d.classes?`<p class="field-help">Labels: ${esc(JSON.stringify(d.classes))}</p>`:''}`:''}${warnings.map(w=>`<p class="plan-warning">${esc(typeof w==='string'?w:w.message)}</p>`).join('')}<p class="field-help">Dataset fingerprint: <span class="mono">${esc((r.fingerprint||'not available').slice(0,18))}</span></p></div>`;}
function trainingStep(){const s=state.draft.spec,image=s.recipe==='image',r=recipe(s.recipe);return `<section class="form-section"><h2>Name your run</h2>${field('name','Run name')}</section><section class="form-section"><h2>Training recipe</h2>${!image&&s.recipe!=='custom'?selectField('recipe','Model recipe',state.data.recipes.filter(r=>['starter','pytorch'].includes(r.id)).map(r=>[r.id,r.name]),s.recipe):`<p class="recipe-description">${esc(r?.name||s.recipe)}</p>`}<p class="field-help" style="margin-top:12px">${esc(r?.description||'Your trusted Python script')}</p>${image?field('epochs','Training epochs',{type:'number',min:1,max:1000,step:1,help:'One epoch is one pass through the training images. Preview calculates the step target.'}):''}<details class="advanced-options"><summary>Advanced training settings</summary><div class="fields-grid">${!image?field('steps','Training steps',{type:'number',min:1,max:10000000,step:1}):''}${field('learning_rate','Learning rate',{type:'number',min:.000001,max:10,step:'any'})}${field('batch_size','Batch size',{type:'number',min:1,max:65536,step:1})}${field('seed','Random seed',{type:'number',min:0,max:2147483647,step:1})}${selectField('device','Device preference',[['auto','Automatic'],['cpu','CPU'],['cuda','CUDA GPU required']],s.device)}</div></details><div class="setup-inline"><p>Missing a dependency? Install it in the app’s Python environment, then recheck hardware.</p><div class="button-row">${action('environment','Prepare CPU training','cpu')}${action('environment','Prepare CUDA training','cuda')}${action('hardware','Recheck hardware')}</div><div id="environment-task">${environmentTaskView()}</div></div></section>`;}
function computeStep(){const d=state.draft,s=d.spec,ps=state.data.providers.filter(p=>p.integration!=='development');return `<section class="form-section"><h2>Your primary compute resource</h2><p class="field-help">Checked first. Adding a fallback does not change your primary choice.</p><div class="field" style="margin-top:14px"><label for="primary-provider">Primary resource</label><select id="primary-provider" name="primary">${ps.map(p=>`<option value="${p.id}" ${d.primary===p.id?'selected':''}>${esc(p.name)} · ${esc(modeLabel(p))}</option>`).join('')}</select></div><div class="selected-resource"><strong>${esc(connectionLabel(provider(d.primary)))}</strong><p>${esc(quotaSummary(provider(d.primary)))}</p>${action('provider','Set up this resource',d.primary)}</div><h3 style="margin:22px 0 10px">Fallbacks in your order</h3><ol class="fallback-list">${d.fallbacks.map((id,i)=>`<li><span>${esc(providerName(id))}</span><div class="button-row">${i?action('fallback-up','Move up',id):''}${i<d.fallbacks.length-1?action('fallback-down','Move down',id):''}${action('fallback-remove','Remove',id)}</div></li>`).join('')||'<li class="muted">No fallback selected. Another resource will not be chosen automatically.</li>'}</ol><div class="path-control" style="margin-top:13px"><select id="fallback-choice" aria-label="Add fallback resource"><option value="">Choose another resource</option>${ps.filter(p=>p.id!==d.primary&&!d.fallbacks.includes(p.id)).map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select>${action('fallback-add','Add fallback')}</div></section><section class="form-section"><h2>Allowance & session limit</h2><label class="switch-row"><input name="free_only" type="checkbox" ${s.free_only?'checked':''}><span><strong>Use only free allowance</strong><small>Unknown limits are not free entitlement. Local electricity and internet costs are yours.</small></span></label>${!s.free_only?`${field('paid_cap','Reported provider spending limit (USD)',{type:'number',min:.01,max:100000,step:.01,help:'Set and verify the native provider cap, including storage and transfer. The app cannot independently enforce a user-reported cap.'})}<label class="switch-row"><input name="paid_confirmed" type="checkbox" ${s.paid_confirmed?'checked':''}><span><strong>I explicitly allow paid compute for this run</strong></span></label>`:''}${field('runtime_minutes','Session limit (minutes)',{type:'number',min:.05,max:1440,step:'any',help:'Supported recipes save and pause before the training session ends.'})}</section><section class="form-section"><h2>Export location</h2>${pathField('output_dir','Model export folder','export','folder','Each run has its own verified export folder. You can retry export to another location.')}</section>`;}
function reviewStep(){const s=trainingSpec();return `<section class="form-section"><h2>Review this training target</h2><dl class="review-list">${[['Run',s.name],['Recipe',recipe(s.recipe)?.name||s.recipe],['Dataset',s.dataset_path||'Generated tabular sample'],['Resource order',s.providers.map(providerName).join(' → ')],['Target',s.recipe==='image'?`${s.epochs} epochs`:`${s.steps} steps`],['Allowance',s.free_only?'Free-only':`Paid opt-in · reported cap $${s.paid_cap}`],['Session',`${s.runtime_minutes} minutes`],['Output',s.output_dir]].map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl></section><p class="field-help">Preview checks data, dependencies, provider identity, and allowance. No runtime starts during preview.</p><button type="button" class="button primary" data-action="preview" id="preview-button" style="margin-top:15px">Preview training plan ${icon('arrow')}</button><section id="plan-result" class="plan-review" aria-live="polite">${planView()}</section>`;}
function planView(){const p=state.plan;if(!p)return '<p class="field-help">Preview this revision before starting training.</p>';return `<h3 id="plan-heading" tabindex="-1">${p.eligible?`${esc(providerName(p.selected_provider))} is eligible`:'Automatic training is blocked'}</h3>${(p.decisions||[]).map(d=>`<div class="plan-decision"><div class="decision-name"><strong>${esc(providerName(d.provider_id))}</strong>${badge(d.eligible?'ready':'unconnected',d.eligible?'Eligible':d.mode==='guided'?'Guided':'Needs attention')}</div><p>${esc(d.reason)}</p></div>`).join('')}${(p.warnings||[]).map(w=>`<p class="plan-warning">${esc(w)}</p>`).join('')}<div class="plan-actions">${p.eligible?action('launch','Start training','',true):''}${(p.decisions||[]).filter(d=>d.provider_id!=='local'&&d.mode!=='development').map(d=>action('guided',`Prepare ${providerName(d.provider_id)} notebook`,d.provider_id)).join('')}</div><p class="detail-note">Changed data, resources, or limits require a fresh preview.</p>`;}
async function inspectData(){const revision=state.draftRevision;try{const r=await api('/api/datasets/inspect',trainingSpec());if(revision!==state.draftRevision)return false;state.datasetReport=r;state.draft.dataset_report=r;if(r.dataset?.total_steps&&state.draft.spec.recipe==='image')state.draft.spec.steps=r.dataset.total_steps;const el=$('#dataset-report');if(el)el.innerHTML=datasetReportView();const label=$('#label-column-control');if(label)label.innerHTML=labelColumnField();saveDraft();return !r.errors?.length;}catch(e){state.actionError=e.message;const el=$('#dataset-report');if(el)el.innerHTML=errorBox(e.message);return false;}}
async function continueWizard(){const step=state.draft.wizard_step,s=trainingSpec();if(step===0){if(s.recipe==='custom'){if(!s.script_path||!s.trust_script)throw Error('Choose your script and confirm that you trust it.');}else{if(state.draft.dataset_mode==='own'&&!s.dataset_path)throw Error('Choose your dataset path.');if(!await inspectData())throw Error(state.actionError||'Resolve the dataset issues before continuing.');}}if(step===1&&!s.name.trim())throw Error('Give the training run a name.');if(step===2&&!s.free_only&&!s.paid_confirmed)throw Error('Explicitly allow paid compute or keep free-only enabled.');state.draft.wizard_step=Math.min(3,step+1);state.actionError='';await saveDraft();render();focusMain();}
async function previewTraining(){if(!state.draft.spec.free_only&&!state.draft.spec.paid_confirmed)throw Error('Confirm paid compute before previewing.');const request=++state.previewRevision,revision=state.draftRevision,routeId=state.routeRevision,spec=trainingSpec();const p=await api('/api/jobs/preview',spec);if(request!==state.previewRevision||revision!==state.draftRevision||routeId!==state.routeRevision||state.route!=='new')return;state.plan={...p,input:spec,draftRevision:revision};$('#plan-result').innerHTML=planView();$('#plan-heading')?.focus({preventScroll:true});$('#plan-result').scrollIntoView({block:'nearest'});}
async function createTraining(guidedProvider){let p=state.plan;if(!p||p.draftRevision!==state.draftRevision)throw Error('Your settings changed. Preview the current plan again.');const routeId=state.routeRevision,revision=state.draftRevision;let spec={...p.input};if(guidedProvider){spec={...spec,guided:true,providers:[guidedProvider]};p=await api('/api/jobs/preview',spec);if(routeId!==state.routeRevision||revision!==state.draftRevision)return;}if(!p.preview_digest)throw Error('The controller did not issue a preview digest. Refresh and preview again.');const j=await api('/api/jobs',{...spec,preview_digest:p.preview_digest});state.data.jobs.unshift(j);if(guidedProvider)try{await download(`/api/jobs/${j.id}/bundle?provider=${encodeURIComponent(guidedProvider)}`,`multigpu-notebook-${j.id.slice(0,8)}.zip`);}catch(e){toast('The notebook run was prepared, but download failed: '+e.message,true);}if(routeId===state.routeRevision&&revision===state.draftRevision){state.draft=freshDraft();state.plan=null;await saveDraft();location.hash=`job/${j.id}`;}else toast(`Training run created: ${j.name}. Find it in Training runs.`);}

function heading(title,description,extra=''){return `<div class="page-heading"><div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${extra}</div>`;}
function newButton(label='New training'){return `<a class="button primary" href="#new">${icon('plus')}${esc(label)}</a>`;}
function focusMain(){const e=$('#main h1')||$('#main');e.tabIndex=-1;e.focus({preventScroll:true});}
function nav(){const active=state.route==='job'?'jobs':state.route;all('#navigation a').forEach(a=>{const on=a.hash===`#${active}`;a.classList.toggle('active',on);if(on)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#settings-nav').classList.toggle('active',active==='settings');$('#page-crumb').textContent=({overview:'Overview',providers:'Providers',jobs:'Training runs',new:'New training',settings:'Settings',job:state.job?.name||'Training run'})[state.route];}
function initializeNav(){$('#navigation').innerHTML=[['overview','Overview'],['providers','Providers'],['jobs','Training runs']].map(([id,label])=>`<a class="nav-link" href="#${id}">${icon(id)}${label}</a>`).join('');}
function controlFocused(){return !!document.activeElement?.closest('input,select,textarea,button,a,summary')||!!window.getSelection()?.toString();}
function freshness(){$('#controller-dot').className=`status-dot ${state.offline?'error':state.lastGood?'connected':''}`;$('#controller-label').textContent=state.offline?'Controller unavailable':'Local controller connected';$('#refresh-stamp').textContent=state.offline?`Offline · last fetch ${clockTime(state.lastGood)}`:`Fetched ${clockTime(state.lastGood)}`;}
function notifyChanges(previous,jobs){if(!state.notifications||!('Notification'in window)||Notification.permission!=='granted')return;for(const j of jobs){const old=previous.find(p=>p.id===j.id);if(old&&old.status!==j.status&&['completed','paused','error','interrupted','unknown'].includes(j.status))new Notification(`MultiGPU · ${statusLabels[j.status]||j.status}`,{body:j.name});}}
async function refresh(manual=false){if(state.refreshing)return;state.refreshing=true;const revision=state.routeRevision,id=state.jobId;try{const previous=state.data?.jobs||[],data=await api('/api/bootstrap');state.data=data;notifyChanges(previous,data.jobs);if(state.route==='job'&&id){const j=await api(`/api/jobs/${encodeURIComponent(id)}`);if(revision===state.routeRevision&&id===state.jobId)state.job=j;}state.lastGood=new Date();state.offline=false;$('#version-label').textContent=data.app?.version?`v${data.app.version}`:'';$('#main').setAttribute('aria-busy','false');const exe=`"${data.hardware.python||'python'}"`;nativeCommands.kaggle=[`${exe} -m kaggle auth login`,`${exe} -m kaggle quota`];nativeCommands.modal=[`${exe} -m modal setup`];const scripts=(data.hardware.python||'python').replace(/[^\\/]+$/, '');nativeCommands.lightning=[`"${scripts}lightning.exe" login`];if(!$('#provider-dialog').open&&state.route!=='new'&&state.route!=='settings'){if(state.route==='job'&&controlFocused())updateJobLive();else if(state.route==='providers'&&document.activeElement?.id==='provider-search')$('#provider-results').innerHTML=providerResults();else if(!controlFocused())render();}if(state.environmentTask)await pollEnvironment();if(manual)toast('Workspace refreshed. Your inputs are preserved.');}catch(e){state.offline=true;if(!state.data)$('#main').innerHTML=`<div class="error-recovery"><h1>The local controller is unavailable</h1><p>Keep MultiGPU running on this computer, then reconnect.</p>${errorBox(e.message)}${action('refresh','Reconnect','',true)}</div>`;else if(manual)toast(e.message,true);}finally{state.refreshing=false;freshness();}}
async function route(){const ticket=++state.routeRevision;state.previewRevision++;const parts=location.hash.replace(/^#\/?/,'').split('/');state.route=['overview','providers','jobs','new','settings','job'].includes(parts[0])?parts[0]:'overview';state.jobId=state.route==='job'?parts[1]:null;state.actionError='';state.importPreview=null;state.prediction=null;closeMobile(false);if(!state.data)return;if(state.route==='job'){const id=state.jobId;state.job=state.data.jobs.find(j=>j.id===id)||null;try{const result=await api(`/api/jobs/${encodeURIComponent(id)}`);if(ticket!==state.routeRevision||id!==state.jobId)return;state.job=result;}catch(e){if(ticket!==state.routeRevision)return;state.actionError=e.message;}}if(ticket!==state.routeRevision)return;render();window.scrollTo({top:0});focusMain();}
function render(){if(!state.data)return;nav();$('#main').innerHTML=({overview:overviewView,providers:providersView,jobs:historyView,new:newView,settings:enhancedSettingsView,job:jobView})[state.route]();}
function connectionLabel(p){if(!p)return 'Resource unavailable';if(p.id==='local')return state.data.hardware.cuda_available?'CPU & CUDA detected':'CPU available';if(!p.connection?.ready)return p.connection?.checked_at?'Setup needs attention':'Not checked';if(p.connection?.budget?.verified===false&&['modal','lightning'].includes(p.id))return 'Signed in · free-only blocked';return 'Signed in';}
function actualCompute(c){const a=c?.actual_resource;return a?[a.machine,a.status,...(a.gpu_names||[])].filter(Boolean).join(' · ')||'Compute unknown':'Actual hardware not verified';}
function providerResults(){const list=state.data.providers.filter(p=>(state.filter==='all'||state.filter==='gpu'&&['gpu','local','institutional','workspace'].includes(p.kind)||state.filter==='cpu'&&['cpu','local'].includes(p.kind)||state.filter==='guided'&&p.integration!=='automatic'||state.filter==='ready'&&p.connection?.ready)&&`${p.name} ${p.description} ${(p.badges||[]).join(' ')}`.toLowerCase().includes(state.search.toLowerCase()));return `<div class="directory-count">${list.length} resources</div><div class="panel"><table class="provider-table"><thead><tr><th>Provider</th><th>Allowance & access</th><th>Observed connection & compute</th><th>Setup</th></tr></thead><tbody>${list.map(p=>`<tr><td><button class="provider-title" data-action="provider" data-id="${p.id}">${esc(p.name)}</button><div class="provider-type">${esc(modeLabel(p))}</div></td><td><div class="provider-allowance">${esc(p.free_summary)}</div>${safeLink(p.docs_url,'Official source','provider-source')}</td><td><strong class="provider-ready">${esc(connectionLabel(p))}</strong><div class="provider-ready">${esc(actualCompute(p.connection))}</div><div class="provider-ready">${p.connection?.checked_at?'Checked '+esc(shortDate(p.connection.checked_at)):'Not observed yet'}</div></td><td>${action('provider','Set up',p.id)}</td></tr>`).join('')||'<tr><td colspan="4"><div class="empty-row">No resources match your search.</div></td></tr>'}</tbody></table></div>`;}
function historyResults(){const jobs=state.data.jobs.filter(j=>(state.includeArchived||!j.archived)&&(state.historyFilter==='all'||j.status===state.historyFilter)&&`${j.name} ${providerName(j.provider_id)} ${j.id}`.toLowerCase().includes(state.historySearch.toLowerCase()));return `<p class="directory-count">${jobs.length} runs</p><div class="panel">${jobRows(jobs)}</div>`;}
function historyView(){return `${heading('Training runs','Find a run, recover its progress, or repeat its configuration.',newButton())}<div class="filterbar"><label class="search-field">${icon('search')}<input id="history-search" type="search" aria-label="Search training runs" placeholder="Search runs or providers" value="${esc(state.historySearch)}"></label><div class="button-row"><select id="history-filter" aria-label="Filter training status">${[['all','All states'],['running','Training'],['paused','Paused'],['completed','Completed'],['error','Needs attention'],['awaiting_user','Guided notebooks']].map(([id,label])=>`<option value="${id}" ${state.historyFilter===id?'selected':''}>${label}</option>`).join('')}</select><label class="inline-check"><input id="history-archived" type="checkbox" ${state.includeArchived?'checked':''}> Include archived</label></div></div><div id="history-results">${historyResults()}</div>`;}
const baseSettingsView=settingsView;
function enhancedSettingsView(){return baseSettingsView()+`<section class="settings-section"><div class="settings-label"><h2>Prepare this environment</h2><p>Installs dependencies into the Python running this controller.</p></div><div class="settings-content"><div class="button-row">${['cpu','cuda','image'].map(id=>action('environment',`Prepare ${id==='image'?'image dependencies':id.toUpperCase()+' training'}`,id)).join('')}${action('hardware','Recheck hardware')}</div><div id="environment-task">${environmentTaskView()}</div></div></section><section class="settings-section"><div class="settings-label"><h2>Desktop notifications</h2><p>Optional completion, pause, and failure notifications.</p></div><div class="settings-content"><p>${state.notifications?'Enabled in this browser.':'Off. Run summaries still appear in the timeline.'}</p>${action('notifications',state.notifications?'Turn notifications off':'Enable notifications')}<p class="settings-note">The controller and this browser must remain running.</p></div></section>`;}
function environmentTaskView(){const t=state.environmentTask;if(!t)return '';return `<div class="dataset-report"><h3>Environment setup · ${esc(t.status||t.state||'queued')}</h3><p>${esc(t.error||t.message||t.detail||(t.status==='completed'?'Dependencies are ready. Recheck hardware before previewing.':'Preparing dependencies.'))}</p>${t.logs?`<details><summary>Installation log</summary><pre class="log-output">${esc(Array.isArray(t.logs)?t.logs.join('\n'):t.logs)}</pre></details>`:''}</div>`;}
async function pollEnvironment(){const t=state.environmentTask;if(!t?.id||['completed','error','failed','succeeded'].includes(t.status||t.state))return;state.environmentTask=await api(`/api/environment/tasks/${encodeURIComponent(t.id)}`);for(const el of all('#environment-task,#provider-environment-task'))if(!el.contains(document.activeElement))el.innerHTML=environmentTaskView();}
const baseProviderDialog=providerDialog;
function openProvider(id){baseProviderDialog(id);state.providerId=id;state.providerDirty=false;const p=provider(id),c=p.connection||{},form=$('#provider-config'),status=$('.dialog-status');if(['kaggle','modal','lightning'].includes(id))$('.dialog-body').insertAdjacentHTML('afterbegin',`<div class="setup-inline"><p>Prepare the provider tools in this app’s managed environment, then sign in with its native command.</p>${action('environment','Prepare '+p.name+' tools',id)}<div id="provider-environment-task">${environmentTaskView()}</div></div>`);if(id==='lightning'&&form){const user=form.querySelector('[name="user"]');user.insertAdjacentHTML('afterend',`<small>Leave user blank when using an organisation.</small>`);user.closest('.field').insertAdjacentHTML('afterend',`<div class="field"><label for="config-organization">Organisation (instead of user)</label><input id="config-organization" name="organization" value="${esc(c.config?.organization||'')}"></div>`);const machine=form.querySelector('[name="machine"]');machine.placeholder='Blank keeps existing compute; e.g. T4';machine.setAttribute('list','machine-options');form.insertAdjacentHTML('beforeend',`<datalist id="machine-options">${(c.machine_options||[]).map(m=>`<option value="${esc(typeof m==='string'?m:m.name)}">`).join('')}</datalist>`);}status.insertAdjacentHTML('beforeend',`<div class="value-pair"><span>Identity</span><strong>${esc(c.identity?Object.entries(c.identity).filter(([k])=>!['source','verified'].includes(k)).map(([,v])=>v).join(' / '):'Not verified')}</strong></div><div class="value-pair"><span>Actual compute</span><strong>${esc(actualCompute(c))}</strong></div>`);const probeButton=$('[data-action="probe"]');probeButton.innerHTML=form?'Save & check':'Check resource';$('.dialog-body').insertAdjacentHTML('beforeend','<div id="provider-error" role="alert"></div>');}
function closeProvider(){if(state.providerDirty&&!window.confirm('Discard unsaved provider settings?'))return;state.providerDirty=false;$('#provider-dialog').close();}
async function probeProvider(id){const form=$('#provider-config'),config={...(provider(id).connection?.config||{})};if(form)for(const input of all('input',form))config[input.name]=input.type==='checkbox'?input.checked:input.name==='native_spend_limit'?Number(input.value):input.value.trim();if(id==='lightning')config.stop_studio_after_run=!!config.dedicated_studio;provider(id).connection=await api(`/api/providers/${id}/probe`,config);state.providerDirty=false;openProvider(id);toast('Settings saved. Review the observed identity, compute, and allowance.');}
async function choosePath(button){const result=await api('/api/desktop/select-path',{kind:button.dataset.kind,purpose:button.dataset.purpose});if(!result.path)return;const input=$('#'+button.dataset.target);if(input){input.value=result.path;input.dispatchEvent(new Event('input',{bubbles:true}));}}
function openMobile(){$('#app-shell').classList.add('menu-open');$('.workspace-main').inert=true;$('.sidebar').setAttribute('role','dialog');$('.sidebar').setAttribute('aria-modal','true');$('#mobile-menu').setAttribute('aria-expanded','true');$('.sidebar .nav-link')?.focus();}
function closeMobile(restore=true){const wasOpen=$('#app-shell').classList.contains('menu-open');$('#app-shell').classList.remove('menu-open');$('.workspace-main').inert=false;$('.sidebar').removeAttribute('role');$('.sidebar').removeAttribute('aria-modal');$('#mobile-menu').setAttribute('aria-expanded','false');if(wasOpen&&restore)$('#mobile-menu').focus();}
function showError(e){state.actionError=e.message;const el=$('#provider-dialog').open?$('#provider-error'):state.route==='new'?$('#wizard-error'):$('#job-action-error');if(el){el.innerHTML=errorBox(e.message);el.scrollIntoView({block:'nearest'});}else toast(e.message,true);}

function allowed(j,name){if(Array.isArray(j.allowed_actions))return j.allowed_actions.some(a=>a.replaceAll('_','-')===name);return false;}
function jobActionButton(method,label,primary=false){return `<button type="button" class="button ${primary?'primary':''}" data-action="job-action" data-method="${method}">${esc(label)}</button>`;}
function jobView(){const j=state.job;if(!j)return `${heading('Training run unavailable','Return to your runs or refresh the workspace.')}${errorBox(state.actionError)}<a class="button" href="#jobs">Training runs</a>`;const guided=j.execution_mode==='guided'||(!j.execution_mode&&j.spec.guided)||j.status==='awaiting_user';return `<a class="back-link" href="#jobs">${icon('back')} Training runs</a><div class="page-heading job-heading"><div><div class="job-title-row"><h1>${esc(j.name)}</h1>${badge(j.status)}</div><div class="job-meta"><span>${esc(providerName(j.provider_id))}</span><span>${esc(shortDate(j.created_at))}</span><span class="mono">${esc(j.id.slice(0,8))}</span></div></div><div class="button-row">${allowed(j,'pause')?jobActionButton('pause','Save & pause'):''}${allowed(j,'cancel')?jobActionButton('cancel','Cancel run'):''}${allowed(j,'external-stop')?safeLink(provider(j.provider_id)?.docs_url,'Open provider stop controls','button'):''}${allowed(j,'reconcile')?jobActionButton('reconcile','Check provider state',true):''}${allowed(j,'resume')&&j.step<j.total_steps?jobActionButton('resume','Resume training'):''}${allowed(j,'resume')&&j.step<j.total_steps&&!j.spec.providers.includes('local')?action('resume-local','Resume on this computer'):''}${action('repeat','Repeat settings')}${allowed(j,'archive')?action('archive',j.archived?'Restore from archive':'Archive run'):''}</div></div><div id="job-action-error" role="alert">${errorBox(state.actionError)}</div><div id="job-live">${jobLiveView(j)}</div><section class="panel panel-pad" style="margin-top:24px"><h2>Run timeline</h2><div id="job-timeline">${timelineView(j)}</div></section>${guided?guidedControls(j):''}<div class="detail-grid" style="margin-top:24px"><div><section class="panel chart-panel"><div class="section-heading"><h2>Training loss</h2><span class="tiny muted">Observed measurements</span></div><div id="job-chart">${lossChart(j.metrics)}</div></section><section class="panel panel-pad" style="margin-top:24px"><h2>Results & evaluation</h2><div id="job-evaluation">${evaluationView(j)}</div>${allowed(j,'predict')?predictionView(j):''}</section><details class="panel log-panel" id="raw-logs" ${state.rawLogsOpen?'open':''}><summary class="log-toolbar">Raw technical logs</summary><pre class="log-output" id="job-logs">${esc(j.logs||'No raw logs have been received.')}</pre></details></div><aside class="main-column"><section class="panel panel-pad"><h2 class="aside-title">Checkpoint & recovery</h2><div id="job-checkpoint">${checkpointView(j)}</div>${allowed(j,'recover')?action('recover','Recover previous checkpoint'):''}</section><section class="panel panel-pad"><h2 class="aside-title">Export your model</h2>${j.export_path?`<p class="storage-path">${esc(j.export_path)}</p><div class="artifact-actions">${action('artifacts','Download model files')}${allowed(j,'open-export')?jobActionButton('open-export','Open export folder'):''}</div>`:''}${allowed(j,'export')?`<form id="export-form" style="margin-top:15px"><div class="field"><label for="export-directory">Export destination</label><div class="path-control"><input id="export-directory" value="${esc(j.spec.output_dir||state.data.settings.output_dir)}"><button class="button" type="button" data-action="choose-path" data-target="export-directory" data-kind="folder" data-purpose="export">Browse…</button></div></div><button class="button" style="margin-top:12px" type="submit">Verify & export model</button></form>`:'<p class="field-help">Export is available when verified model files are ready.</p>'}</section><section class="panel panel-pad"><h2 class="aside-title">Original training limits</h2><div class="value-pair"><span>Target</span><strong>${number(j.total_steps||j.spec.steps)} steps</strong></div><div class="value-pair"><span>Session</span><strong>${number(j.spec.runtime_minutes,2)} minutes</strong></div><div class="value-pair"><span>Allowance</span><strong>${j.spec.free_only?'Free-only':'Paid · reported provider cap'}</strong></div><p class="detail-note">Resume preserves the model and original target. Provider storage remains under your control.</p></section></aside></div>`;}
function jobLiveView(j){const phases={preparing:'Preparing the environment',waiting:'Waiting for compute',submitting:'Submitting to your provider',training:'Training the model',evaluating:'Evaluating held-out data',exporting:'Verifying and exporting model files',collecting:'Collecting provider output',checkpointing:'Saving a recovery point'};const label=j.status==='completed'?'Model ready':phases[j.phase]||statusLabels[j.status]||String(j.phase||j.status).replaceAll('_',' ');return `<div class="notice ${['unknown','interrupted','submission_unknown'].includes(j.status)?'warning':j.status==='error'?'error':''}"><strong>${esc(label)}</strong><p>${esc(j.message||'Waiting for the next controller observation.')}</p><p class="field-help">Connection: ${esc(j.connection_status||'not observed')} · Worker event: ${esc(shortDate(j.last_worker_event_at))} · Training progress: ${esc(shortDate(j.last_progress_at))}</p></div><div class="job-stats"><div class="job-stat"><span>Training steps</span><strong>${number(j.step||0)} <small>/ ${number(j.total_steps||j.spec.steps)}</small></strong></div><div class="job-stat"><span>Latest loss</span><strong>${number(j.loss,5)}</strong></div><div class="job-stat"><span>Training elapsed</span><strong>${elapsed(j.elapsed_seconds)}</strong></div><div class="job-stat"><span>Reported device</span><strong class="device-value">${esc(j.device||'Not reported')}</strong></div></div>`;}
function timelineView(j){const labels={queued:'Run queued',preparing:'Preparing environment',submitted:'Submitted to provider',checkpoint:'Checkpoint saved',summary:'Training summary',completed:'Training completed',paused:'Progress saved; training paused',error:'Training needs attention',export:'Model exported',import:'Notebook results imported',reconciled:'Provider state checked'};const events=(j.events||[]).filter(e=>e.type!=='metric').slice(-8);return events.length?`<ol class="timeline">${events.map(e=>`<li><span class="timeline-time">${esc(shortDate(e.timestamp))}</span><div><strong>${esc(labels[e.type]||String(e.type||'Update').replaceAll('_',' '))}</strong><p>${esc(e.message||(e.step!=null?`Step ${number(e.step)} of ${number(e.total_steps||j.total_steps)}`:''))}</p></div></li>`).join('')}</ol>`:'<p class="field-help" style="margin-top:12px">No worker events have been received. Training progress has not been inferred.</p>';}
function checkpointView(j){const c=j.checkpoint;return `<dl class="detail-list"><div><dt>Last verified checkpoint</dt><dd>${c?`Step ${number(c.step)} · ${esc(shortDate(c.at||c.timestamp))}`:'No local checkpoint verified yet'}</dd></div><div><dt>Local location</dt><dd class="mono">${esc(c?.local_path||c?.path||'Not available')}</dd></div>${c?.remote_path?`<div><dt>Provider location</dt><dd class="mono">${esc(c.remote_path)}</dd></div>`:''}</dl><p class="detail-note">A remote location does not mean the checkpoint has been downloaded and verified locally.</p>`;}
function evaluationView(j){const e=j.evaluation;if(!e||!Object.keys(e).length)return '<p class="field-help" style="margin-top:12px">Validation results have not been reported. Training loss alone does not measure held-out performance.</p>';return `<dl class="report-grid">${[['accuracy','Validation accuracy'],['validation_accuracy','Validation accuracy'],['validation_loss','Validation loss'],['loss',e.split==='training_only_legacy'?'Training loss':'Validation loss'],['samples','Evaluated examples'],['train_rows','Training examples'],['validation_rows','Validation examples']].filter(([k])=>e[k]!=null).map(([k,label])=>`<div><dt>${label}</dt><dd>${k.includes('accuracy')?number(Number(e[k])*100,2)+'%':number(e[k],5)}</dd></div>`).join('')}</dl>${e.warning?`<p class="field-help" style="margin-top:12px">${esc(e.warning)}</p>`:''}${e.classes?`<p class="field-help">Class mapping: ${esc(JSON.stringify(e.classes))}</p>`:''}${e.confusion_matrix?`<details class="advanced-options"><summary>Confusion matrix</summary><pre class="example-code">${esc(JSON.stringify(e.confusion_matrix,null,2))}</pre></details>`:''}`;}
function predictionView(j){const image=j.spec.recipe==='image';return `<form id="prediction-form" class="prediction-form"><h3>Try a prediction</h3><p class="field-help">Runs locally from the verified exported model. Use the feature order in input_schema.json from your export.</p><div class="field" style="margin-top:12px"><label for="prediction-input">${image?'Image file path':'Numeric features, in dataset column order'}</label><div class="path-control"><input id="prediction-input" placeholder="${image?'Full image path':'e.g. 1.2, 3.4, 5.6'}">${image?'<button class="button" type="button" data-action="choose-path" data-target="prediction-input" data-kind="file" data-purpose="image">Browse…</button>':''}</div></div><button class="button" style="margin-top:12px" type="submit">Run prediction</button><div id="prediction-result" aria-live="polite">${state.prediction?`<pre class="example-code">${esc(JSON.stringify(state.prediction,null,2))}</pre>`:''}</div></form>`;}
function guidedControls(j){return `<section class="panel panel-pad" style="margin-top:24px"><h2>Run this notebook in your account</h2><p class="field-help" style="margin-top:9px">Download the bundle, open its notebook in your account, select authorised compute, and run it there. This dashboard cannot infer live progress for a manually launched notebook.</p><div class="button-row" style="margin-top:14px">${allowed(j,'bundle')?action('bundle',j.checkpoint?'Download continuation notebook':'Download notebook bundle','',true):''}${safeLink(provider(j.provider_id)?.signup_url||provider(j.provider_id)?.docs_url,'Open provider account','button')}</div>${allowed(j,'import')?`<form id="import-results-form" style="margin-top:22px"><h3>Bring your results back</h3><div class="field" style="margin-top:12px"><label for="import-path">Downloaded output folder or ZIP</label><div class="path-control"><input id="import-path" required placeholder="Full path on this computer"><button class="button" type="button" data-action="choose-path" data-target="import-path" data-kind="file" data-purpose="import">Browse…</button></div></div><button type="submit" class="button" style="margin-top:12px">Preview & verify results</button><div id="import-preview" aria-live="polite">${importPreviewView()}</div></form>`:''}</section>`;}
function importPreviewView(){const p=state.importPreview;if(!p)return '';return `<div class="dataset-report"><h3>Import verification</h3>${(p.errors||[]).map(errorBox).join('')}<pre class="example-code">${esc(JSON.stringify(Object.fromEntries(Object.entries(p).filter(([k])=>!['preview_digest','path'].includes(k))),null,2))}</pre>${p.preview_digest&&!p.errors?.length?`<label class="switch-row"><input id="allow-rollback" type="checkbox"><span><strong>Allow replacing newer progress with an earlier checkpoint</strong><small>Required only if this import is behind the saved run.</small></span></label>${action('import-commit','Import verified results')}`:''}</div>`;}
function updateJobLive(){const j=state.job;if(!j||!$('#job-live'))return;$('#job-live').innerHTML=jobLiveView(j);$('#job-timeline').innerHTML=timelineView(j);$('#job-chart').innerHTML=lossChart(j.metrics);$('#job-checkpoint').innerHTML=checkpointView(j);$('#job-evaluation').innerHTML=evaluationView(j);const log=$('#job-logs');if(log&&!log.contains(document.activeElement)){const bottom=log.scrollHeight-log.scrollTop-log.clientHeight<25,position=log.scrollTop;log.textContent=j.logs||'No raw logs received.';log.scrollTop=bottom?log.scrollHeight:position;}}
async function jobAction(method,body={}){const id=state.job?.id,revision=state.routeRevision;if(!id)throw Error('No run is selected.');const result=await api(`/api/jobs/${id}/${method}`,body);if(revision!==state.routeRevision||id!==state.jobId)return result;state.job=await api(`/api/jobs/${id}`);if(revision!==state.routeRevision||id!==state.jobId)return result;const index=state.data.jobs.findIndex(j=>j.id===id);if(index>=0)state.data.jobs[index]=state.job;else state.data.jobs.unshift(state.job);state.actionError='';render();toast(method==='pause'?'Checkpoint and pause requested.':method==='cancel'?'Cancellation requested. Check the confirmed provider state.':method==='export'?'Model files verified and exported.':'Run updated.');return result;}
function repeatSettings(){const j=state.job,b=freshDraft(),s={...b.spec,...j.spec};for(const k of ['id','attempt_id','resume_from','guided','preview_digest'])delete s[k];Object.assign(s,{name:`${j.name} (copy)`,free_only:true,paid_cap:0,paid_confirmed:false,trust_script:false});state.draft={...b,spec:s,primary:s.providers[0],fallbacks:s.providers.slice(1),dataset_mode:s.dataset_path?'own':'sample'};changedDraft(true);saveDraft();location.hash='new';}

async function runAction(button){const a=button.dataset.action;if(a==='filter'){state.filter=button.dataset.filter;all('.filter-tab').forEach(b=>{b.classList.toggle('active',b.dataset.filter===state.filter);b.setAttribute('aria-pressed',String(b.dataset.filter===state.filter));});$('#provider-results').innerHTML=providerResults();return;}if(a==='provider'){openProvider(button.dataset.id);return;}if(a==='close-dialog'){closeProvider();return;}if(a==='wizard-back'||a==='wizard-step'){state.previewRevision++;state.draft.wizard_step=a==='wizard-back'?Math.max(0,state.draft.wizard_step-1):Number(button.dataset.step);saveDraft();render();focusMain();return;}if(a==='fallback-add'){const id=$('#fallback-choice').value;if(id&&!state.draft.fallbacks.includes(id)){state.draft.fallbacks.push(id);changedDraft();render();}return;}if(a.startsWith('fallback-')){const id=button.dataset.id,list=state.draft.fallbacks,i=list.indexOf(id);if(a==='fallback-remove')list.splice(i,1);else{const next=a==='fallback-up'?i-1:i+1;if(next>=0&&next<list.length)[list[i],list[next]]=[list[next],list[i]];}changedDraft();render();return;}if(a==='repeat'){repeatSettings();return;}button.disabled=true;try{if(a==='refresh'||a==='retry')await refresh(true);else if(a==='probe')await probeProvider(button.dataset.id);else if(a==='choose-path')await choosePath(button);else if(a==='inspect-data'){if(!await inspectData())throw Error(state.actionError||'Resolve the reported dataset issues.');}else if(a==='preview')await previewTraining();else if(a==='launch')await createTraining();else if(a==='guided')await createTraining(button.dataset.id);else if(a==='job-action')await jobAction(button.dataset.method);else if(a==='resume-local')await jobAction('resume',{providers:[...new Set(['local',...state.job.spec.providers])]});else if(a==='recover')await jobAction('recover',{checkpoint:'previous'});else if(a==='archive')await jobAction('archive',{archived:!state.job.archived});else if(a==='bundle'||a==='artifacts')await download(`/api/jobs/${state.job.id}/${a==='bundle'?'bundle?provider='+encodeURIComponent(state.job.provider_id):'artifacts'}`,`multigpu-${a}-${state.job.id.slice(0,8)}.zip`);else if(a==='copy'){await navigator.clipboard.writeText(button.dataset.value||button.dataset.id);toast('Command copied.');}else if(a==='hardware'){state.data.hardware=await api('/api/hardware/recheck',{});toast('Local hardware detection refreshed.');if(state.route==='settings')render();}else if(a==='environment'){state.environmentTask=await api('/api/environment/setup',{profile:button.dataset.id});for(const el of all('#environment-task,#provider-environment-task'))el.innerHTML=environmentTaskView();toast('Environment setup started. Installation output is available in Settings.');}else if(a==='import-commit'){if(!state.importPreview?.preview_digest)throw Error('Preview the downloaded results again.');await jobAction('import',{path:$('#import-path').value.trim(),preview_digest:state.importPreview.preview_digest,allow_rollback:$('#allow-rollback').checked});state.importPreview=null;}else if(a==='notifications'){if(state.notifications){state.notifications=false;localStorage.setItem('multigpu.notifications','off');}else if(!('Notification'in window))throw Error('This browser does not support desktop notifications.');else{state.notifications=await Notification.requestPermission()==='granted';localStorage.setItem('multigpu.notifications',state.notifications?'on':'off');if(!state.notifications)throw Error('Notifications were not enabled. Review browser notification settings if needed.');}render();}}finally{if(button.isConnected)button.disabled=false;}}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(button){event.preventDefault();runAction(button).catch(showError);}});
document.addEventListener('input',event=>{const input=event.target;if(input.id==='provider-search'){state.search=input.value;$('#provider-results').innerHTML=providerResults();return;}if(input.id==='history-search'){state.historySearch=input.value;$('#history-results').innerHTML=historyResults();return;}if(input.closest('#provider-config')){state.providerDirty=true;return;}if(input.id==='import-path'){state.importPreview=null;const el=$('#import-preview');if(el)el.innerHTML='';return;}if(!input.closest('#training-form')||!input.name)return;const d=state.draft,s=d.spec,name=input.name;let redraw=false,dataset=false;if(name==='task'){const id=input.value==='image'?'image':input.value==='custom'?'custom':'starter';s.recipe=id;Object.assign(s,recipe(id)?.defaults||{batch_size:id==='image'?16:32,learning_rate:id==='image'?.001:.05,steps:500,epochs:5});d.dataset_mode=id==='image'?'own':'sample';s.dataset_path='';s.label_column='';s.trust_script=false;redraw=true;dataset=true;}else if(name==='dataset_mode'){d.dataset_mode=input.value;redraw=true;dataset=true;}else if(name==='primary'){d.primary=input.value;d.fallbacks=d.fallbacks.filter(id=>id!==d.primary);redraw=true;}else{s[name]=input.type==='checkbox'?input.checked:input.type==='number'?Number(input.value):input.value;if(['dataset_path','label_column','script_path'].includes(name))dataset=true;if(name==='script_path')s.trust_script=false;if(name==='free_only'){s.paid_confirmed=false;if(s.free_only)s.paid_cap=0;redraw=true;}if(name==='recipe'){Object.assign(s,recipe(input.value)?.defaults||{});redraw=true;dataset=true;}}changedDraft(dataset);if(redraw){const id=input.id;render();if(id)$('#'+id)?.focus();}});
document.addEventListener('change',event=>{if(event.target.id==='history-filter'){state.historyFilter=event.target.value;$('#history-results').innerHTML=historyResults();}if(event.target.id==='history-archived'){state.includeArchived=event.target.checked;$('#history-results').innerHTML=historyResults();}});
document.addEventListener('submit',async event=>{const form=event.target;if(!['training-form','settings-form','provider-config','import-results-form','prediction-form','export-form'].includes(form.id))return;event.preventDefault();const button=form.querySelector('[type="submit"]');if(button)button.disabled=true;try{if(form.id==='training-form')await continueWizard();else if(form.id==='provider-config')await probeProvider(state.providerId);else if(form.id==='settings-form'){state.data.settings=await api('/api/settings',{output_dir:$('#settings-output').value.trim()});toast('Default model export folder saved.');}else if(form.id==='export-form')await jobAction('export',{output_dir:$('#export-directory').value.trim()});else if(form.id==='prediction-form'){const value=$('#prediction-input').value.trim(),body=state.job.spec.recipe==='image'?{image_path:value}:{features:value.split(',').map(x=>Number(x.trim()))};if(body.features&&(!value||body.features.some(x=>!Number.isFinite(x))))throw Error('Enter numeric features separated by commas.');state.prediction=await api(`/api/jobs/${state.job.id}/predict`,body);$('#prediction-result').innerHTML=`<pre class="example-code">${esc(JSON.stringify(state.prediction,null,2))}</pre>`;}else if(form.id==='import-results-form'){state.importPreview=await api(`/api/jobs/${state.job.id}/import`,{path:$('#import-path').value.trim(),preview:true});$('#import-preview').innerHTML=importPreviewView();}}catch(e){showError(e);}finally{if(button?.isConnected)button.disabled=false;}});
$('#refresh-button').addEventListener('click',()=>refresh(true));$('#mobile-menu').addEventListener('click',()=>openMobile());$('#mobile-menu-close')?.addEventListener('click',()=>closeMobile());$('.skip-link').addEventListener('click',event=>{event.preventDefault();$('#main').focus();});
$('#provider-dialog').addEventListener('cancel',event=>{event.preventDefault();closeProvider();});$('#provider-dialog').addEventListener('click',event=>{if(event.target!==event.currentTarget)return;const r=event.currentTarget.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeProvider();});
document.addEventListener('keydown',event=>{if(!$('#app-shell').classList.contains('menu-open'))return;if(event.key==='Escape'){event.preventDefault();closeMobile();}else if(event.key==='Tab'){const links=all('a,button,input,select',$('.sidebar')).filter(e=>e.offsetParent!==null),first=links[0],last=links.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
document.addEventListener('toggle',event=>{if(event.target.id==='raw-logs')state.rawLogsOpen=event.target.open;},true);
window.addEventListener('hashchange',route);window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(window.innerWidth>1000)closeMobile(false);if(state.route==='job')updateJobLive();},120);});
async function start(){initializeNav();try{state.notifications=localStorage.getItem('multigpu.notifications')==='on';}catch{}await refresh();if(!state.data)return;try{state.draft=normalizeDraft(await api('/api/draft'));state.datasetReport=state.draft.dataset_report||null;}catch{state.draft=freshDraft();}await route();setInterval(()=>{if(!document.hidden||state.notifications)refresh();},5000);}
start();
